"""FastAPI dependency helpers."""

from __future__ import annotations

from typing import Annotated

from fastapi import Depends, Path, Request

from app.services.container import Container


def get_container(request: Request) -> Container:
    container: Container = request.app.state.container
    return container


ContainerDep = Annotated[Container, Depends(get_container)]

# Document IDs are generated by us ("doc_" + 16 hex chars). Validating the format
# rejects junk early and keeps arbitrary strings out of database filters.
DocumentIdPath = Annotated[
    str, Path(pattern=r"^doc_[0-9a-f]{16}$", description="Document ID, e.g. doc_1a2b3c4d5e6f7a8b")
]
